def get_response(intent: str) -> str:
    """
    Returns the chatbot response for a given predicted intent.
    Provides a fallback message if the intent is unrecognised.
    """
    fallback_message = (
        "I'm sorry, I couldn't process your request. "
        "Please rephrase your banking question or contact human support."
    )
    return responses.get(intent, fallback_message)